function installDemoPack(){const raw=localStorage.getItem(key);if(raw&&!localStorage.getItem('daraei-backup-before-rich-v1'))localStorage.setItem('daraei-backup-before-rich-v1',raw);let added=0;for(const [code,title,owner,reviewer,status,pc,due,collaborators,discipline,description]of demoDefinitions){const id='darayi-demo-'+code;if(tasks.some(t=>t.id===id))continue;const t={id,code:'DR-'+code,title,owner,creator:reviewer,assignedBy:reviewer,status,progress:pc,collaborators,discipline,description,due:day(due),start:day(-5),created:day(-7)+'T08:30:00Z',priority:'عادی',revision:2,completed:null,demo:true,sample:false,reports:[],requests:[],submissions:[],approvals:[],assignmentHistory:[],demoVersions:[]};t.reports.push({person:reviewer,time:day(-6)+'T08:30:00Z',text:'این کار برای پیگیری در تیم ثبت شده است. نتیجه و مدارک را همین‌جا قرار دهید.',hours:0,type:'feedback'});if(pc>0)t.reports.push({person:owner,time:day(-2)+'T10:00:00Z',text:status==='متوقف‌شده'?'پیگیری انجام شد؛ منتظر اعلام زمان تأمین هستیم.':'بررسی اولیه انجام شد و نتیجه در نسخه پیوست ثبت شده است.',hours:2.5,type:'report',progress:pc});if(status==='نیازمند اصلاح')t.reports.push({person:reviewer,time:day(-1)+'T09:15:00Z',text:'لطفاً محل دقیق مغایرت و راهکار پیشنهادی را در نسخه بعدی مشخص کنید.',hours:0,type:'feedback'});if(status==='متوقف‌شده')t.reason='منتظر اعلام زمان تأمین و هماهنگی ارسال';if(['101','103','106','111'].includes(code)){t.demoVersions=[{id:id+'-v1',label:'گزارش کنترل · نسخه اول',by:owner,created:day(-4)+'T09:00:00Z',files:[{url:'demo-assets/darayi-review-v1.pdf',name:'گزارش-کنترل-نسخه۱.pdf',type:'application/pdf'}]},{id:id+'-v2',label:'گزارش کنترل · نسخه اصلاح‌شده',by:owner,created:day(-1)+'T09:00:00Z',files:[{url:'demo-assets/darayi-review-v2.pdf',name:'گزارش-کنترل-نسخه۲.pdf',type:'application/pdf'},{url:'demo-assets/checklist.csv',name:'چک‌لیست-کنترل.csv',type:'text/csv;charset=utf-8'}]}]}else if(['102','104','108','109'].includes(code)){t.demoVersions=[{id:id+'-v1',label:code==='108'?'صورت‌جلسه هماهنگی':'فایل کار و چک‌لیست',by:owner,created:day(-2)+'T09:30:00Z',files:[{url:'demo-assets/checklist.csv',name:'چک‌لیست-پیگیری.csv',type:'text/csv;charset=utf-8'},{url:'demo-assets/site-notes.txt',name:'یادداشت-هماهنگی.txt',type:'text/plain;charset=utf-8'}]}]}
if(status==='آماده بررسی'||status==='بسته‌شده'){const sub={id:id+'-submission',at:day(-1)+'T10:30:00Z',by:owner,versionId:t.demoVersions.at(-1)?.id||null,revision:2,description:t.description};t.submissions.push(sub);t.reviewSubmission=sub;t.reports.push({person:owner,time:sub.at,text:'نسخه نهایی کار برای بررسی ارسال شد.',type:'event',hours:0});if(status==='بسته‌شده'){const approval={id:id+'-approval',at:day(-1)+'T13:00:00Z',by:reviewer,versionId:sub.versionId,submissionId:sub.id,description:t.description,owner,revision:2};t.approvals.push(approval);t.completed=approval.at;t.finalVersionId=sub.versionId;t.approvedBy=reviewer;t.reports.push({person:reviewer,time:approval.at,text:'مدارک بررسی و تأیید نهایی شد. نسخه تأییدشده در پرونده کار باقی می‌ماند.',type:'feedback',hours:0})}}tasks.push(t);added++}
for(const [id,title,owner,due]of [['demo-milestone-a','تحویل بسته نقشه‌های مرحله دوم',8,7],['demo-milestone-b','جمع‌بندی پیشرفت و برنامه هفته آینده',6,5]])if(!deliveries.some(d=>d.id===id))deliveries.push({id,title,owner,due:day(due),start:day(0),status:'در حال اجرا',description:'موعد نمونه برای بررسی تقویم و تایملاین پروژه.',sample:true,demo:true});normalizeWorkflowTasks();localStorage.setItem(key,JSON.stringify(tasks));localStorage.setItem('daraei-deliveries-v1',JSON.stringify(deliveries));const sampleNotices=[{id:'demo-notice-review-pm',recipient:4,actor:6,taskId:'darayi-demo-101',text:'«بازبینی نقشه اجرایی طبقه دوم» آماده بررسی و تأیید نهایی است.'},{id:'demo-notice-review-supervisor',recipient:5,actor:6,taskId:'darayi-demo-108',text:'صورت‌جلسه هماهنگی کارگاه برای بررسی شما ارسال شده است.'},{id:'demo-notice-feedback-expert',recipient:6,actor:4,taskId:'darayi-demo-104',text:'برای گزارش پیشرفت هفتگی، بازخورد تازه ثبت شده است.'}];for(const n of sampleNotices)if(!notices.some(x=>x.id===n.id))notices.push({...n,created:day(-1)+'T09:00:00Z',read:false,demo:true});localStorage.setItem('daraei-notices-v1',JSON.stringify(notices));return added}
let demoInstallError=false;try{installDemoPack()}catch{demoInstallError=true}
async function ensureDemoFiles(t){if(!t.demoVersions?.length)return;const db=await workflowDB;let existing=await taskVersions(t.id);const missing=t.demoVersions.filter(v=>!existing.some(e=>e.id===v.id));for(const v of missing){const files=await Promise.all(v.files.map(async(f,i)=>{const response=await fetch(f.url);if(!response.ok)throw Error('فایل نمونه بارگذاری نشد');const blob=new Blob([await response.arrayBuffer()],{type:f.type});return {id:v.id+'-f'+i,name:f.name,size:blob.size,type:f.type,blob}}));const tx=db.transaction(['versions','files'],'readwrite'),done=transactionDone(tx);try{const found=await requestResult(tx.objectStore('versions').get(v.id));if(!found){files.forEach(f=>tx.objectStore('files').add(f));tx.objectStore('versions').add({id:v.id,taskId:t.id,label:v.label,created:v.created,by:v.by,demo:true,files:files.map(({blob,...meta})=>meta)})}await done}catch(e){await done.catch(()=>{});throw e}}}
